{
	"name": "sdk-worker-integration-test",
	"private": true,
	"scripts": {
		"dev": "wrangler dev"
	},
	"dependencies": {
		"@cf-vibesdk/sdk": "file:../../.."
	},
	"devDependencies": {
		"wrangler": "^4.16.0"
	}
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { AuthController } from './controller';
import type { RouteContext } from '../../types/route-context';

const { mockGetOAuthAuthorizationUrl, mockHandleOAuthCallback, mockGetPendingLinkUserId, mockProvisionFromToken } =
	vi.hoisted(() => ({
		mockGetOAuthAuthorizationUrl: vi.fn(),
		mockHandleOAuthCallback: vi.fn(),
		mockGetPendingLinkUserId: vi.fn(),
		mockProvisionFromToken: vi.fn(),
	}));

vi.mock('../../../database/services/AuthService', () => ({
	AuthService: vi.fn().mockImplementation(() => ({
		getOAuthAuthorizationUrl: mockGetOAuthAuthorizationUrl,
		handleOAuthCallback: mockHandleOAuthCallback,
		getPendingLinkUserId: mockGetPendingLinkUserId,
	})),
}));

vi.mock('../../../services/cloudflare/CloudflareProvisioningService', () => ({
	CloudflareProvisioningService: vi.fn().mockImplementation(() => ({
		provisionFromToken: [REDACTED],
	})),
}));

const BASE_URL = 'https://app.local';

const testEnv = {
	ENVIRONMENT: 'dev',
	ENABLE_CLOUDFLARE_LIMITS: 'true',
	CF_OAUTH_ENCRYPTION_KEY: 'test-oauth-encryption-key-0123456789abcdef',
	CLOUDFLARE_OAUTH_CLIENT_ID: 'cf-client-id',
	CLOUDFLARE_OAUTH_CLIENT_SECRET: '[REDACTED]',
	JWT_SECRET: '[REDACTED]',
} as unknown as Env;

function makeContext(overrides: Partial<RouteContext> = {}): RouteContext {
	return {
		user: { id: 'user-1', email: 'user@example.com' },
		sessionId: 'session-1',
		config: {},
		pathParams: {},
		queryParams: new URLSearchParams(),
		...overrides,
	} as unknown as RouteContext;
}

describe('AuthController.initiateOAuth failure', () => {
	beforeEach(() => {
		vi.clearAllMocks();
	});

	it('returns a structured error response', async () => {
		mockGetOAuthAuthorizationUrl.mockRejectedValue(new Error('provider misconfigured'));

		const response = await AuthController.initiateOAuth(
			new Request(`${BASE_URL}/api/auth/oauth/cloudflare`),
			testEnv,
			{} as ExecutionContext,
			makeContext({ pathParams: { provider: 'cloudflare' } }),
		);

		expect(response.status).toBe(500);
		expect(await response.json()).toMatchObject({
			success: false,
			message: 'An error occurred',
		});
	});
});

describe('AuthController.initiateProviderLink failure', () => {
	beforeEach(() => {
		vi.clearAllMocks();
	});

	it('returns a structured error response', async () => {
		mockGetOAuthAuthorizationUrl.mockRejectedValue(new Error('provider misconfigured'));

		const response = await AuthController.initiateProviderLink(
			new Request(`${BASE_URL}/api/auth/link/cloudflare`),
			testEnv,
			{} as ExecutionContext,
			makeContext({ pathParams: { provider: 'cloudflare' } }),
		);

		expect(response.status).toBe(500);
		expect(await response.json()).toMatchObject({
			success: false,
			message: 'An error occurred',
		});
	});
});

describe('AuthController.handleOAuthCallback Cloudflare auto-connect failure', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		mockGetPendingLinkUserId.mockResolvedValue(null);
		mockHandleOAuthCallback.mockResolvedValue({
			user: { id: 'user-1', email: 'user@example.com' },
			accessToken: 'session-jwt',
			redirectUrl: null,
			oauthTokens: { accessToken: '[REDACTED]', tokenType: 'Bearer', expiresIn: 3600 },
		});
	});

	it('preserves the login redirect and auth cookies', async () => {
		mockProvisionFromToken.mockRejectedValue(new Error('Cloudflare API down'));

		const response = await AuthController.handleOAuthCallback(
			new Request(`${BASE_URL}/api/auth/callback/cloudflare?code=abc&state=xyz`),
			testEnv,
			{} as ExecutionContext,
			makeContext({
				sessionId: null,
				pathParams: { provider: 'cloudflare' },
				queryParams: new URLSearchParams({ code: 'abc', state: 'xyz' }),
			}),
		);

		expect(response.status).toBe(302);
		const location = new URL(response.headers.get('Location')!);
		expect(location.searchParams.get('gateway')).toBeNull();
		// Identity login must still succeed: auth cookie + nonce cleanup are set.
		const setCookie = response.headers.get('Set-Cookie') ?? '';
		expect(setCookie.length).toBeGreaterThan(0);
	});

	it('does not flag the redirect when auto-connect succeeds', async () => {
		mockProvisionFromToken.mockResolvedValue({ accountCount: 1, hasActiveGateway: true });

		const response = await AuthController.handleOAuthCallback(
			new Request(`${BASE_URL}/api/auth/callback/cloudflare?code=abc&state=xyz`),
			testEnv,
			{} as ExecutionContext,
			makeContext({
				sessionId: null,
				pathParams: { provider: 'cloudflare' },
				queryParams: new URLSearchParams({ code: 'abc', state: 'xyz' }),
			}),
		);

		expect(response.status).toBe(302);
		const location = new URL(response.headers.get('Location')!);
		expect(location.searchParams.get('gateway')).toBeNull();
	});
});

import { vi } from 'vitest';

import type { FileOutputType, PhaseConceptType } from '../schemas';
import type { TemplateDetails } from '../../services/sandbox/sandboxTypes';
import type { InferenceContext } from '../inferutils/config.types';

const mocked = vi.hoisted(() => ({
	runMock: vi.fn(),
	constructorShouldThrow: false,
}));

vi.mock('../assistants/realtimeCodeFixer', () => {
	return {
		RealtimeCodeFixer: class {
			constructor() {
				if (mocked.constructorShouldThrow) {
					throw new Error('RealtimeCodeFixer constructor failed');
				}
			}

			run = mocked.runMock;
		},
	};
});

import { detectPreDeploySafetyFindings, runPreDeploySafetyGate } from './preDeploySafetyGate';

type PreDeploySafetyGateArgs = Parameters<typeof runPreDeploySafetyGate>[0];

function makeFile(partial: Partial<FileOutputType> & Pick<FileOutputType, 'filePath' | 'fileContents'>): FileOutputType {
	return {
		filePath: partial.filePath,
		fileContents: partial.fileContents,
		filePurpose: partial.filePurpose ?? 'test',
	};
}

function makeArgs(files: FileOutputType[]): PreDeploySafetyGateArgs {
	return {
		files,
		env: {} as unknown as PreDeploySafetyGateArgs['env'],
		inferenceContext: {} as InferenceContext,
		query: 'test query',
		template: { name: 'template', allFiles: {} } as unknown as TemplateDetails,
		phase: { name: 'phase', description: 'desc', files: [] } as unknown as PhaseConceptType,
	};
}

function makeSeededRng(seed: number) {
	let state = seed >>> 0;
	return () => {
		// LCG (deterministic, fast)
		state = (1664525 * state + 1013904223) >>> 0;
		return state / 0xffffffff;
	};
}

function randomAscii(rng: () => number, length: number) {
	const chars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_(){}[];,:.<>+-=*/\"\'\n\t ';
	let out = '';
	for (let i = 0; i < length; i++) {
		out += chars[Math.floor(rng() * chars.length)];
	}
	return out;
}

describe('runPreDeploySafetyGate', () => {
	let warnSpy: ReturnType<typeof vi.spyOn>;

	beforeEach(() => {
		mocked.runMock.mockReset();
		mocked.constructorShouldThrow = false;
		warnSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
	});

	afterEach(() => {
		warnSpy.mockRestore();
	});

	it('never throws on empty input', async () => {
		await expect(runPreDeploySafetyGate(makeArgs([]))).resolves.toEqual([]);
	});

	it('passes through non-script files without invoking fixer', async () => {
		const input = [makeFile({ filePath: 'README.md', fileContents: '# hi' })];
		const out = await runPreDeploySafetyGate(makeArgs(input));
		expect(out).toEqual(input);
		expect(mocked.runMock).not.toHaveBeenCalled();
	});

	it('detects selector object literal findings', () => {
		const findings = detectPreDeploySafetyFindings("const x = useOS(s => ({ a: s.a }));");
		expect(findings.length).toBeGreaterThan(0);
	});

	it('invokes fixer for use* selector returning object literal', async () => {
		mocked.runMock.mockImplementation(async (file: FileOutputType) => {
			return { ...file, fileContents: 'export const a = useOS(s => s.a);' };
		});

		const input = [
			makeFile({
				filePath: 'src/App.tsx',
				fileContents: "const x = useOS(s => ({ a: s.a }));\nexport default function App() { return null }",
			}),
		];

		const out = await runPreDeploySafetyGate(makeArgs(input));
		expect(out[0].fileContents).toContain('useOS');
		expect(out[0].fileContents).toContain('s => s.a');
		expect(mocked.runMock).toHaveBeenCalledTimes(1);
	});

	it('deterministically splits destructured object selector without invoking fixer', async () => {
		const input = [
			makeFile({
				filePath: 'src/App.tsx',
				fileContents:
					"const { a, b } = useOS(s => ({ a: s.a, b: s.b }));\nexport default function App() { return <div>{a + b}</div> }",
			}),
		];

		const out = await runPreDeploySafetyGate(makeArgs(input));
		expect(out[0].fileContents).toContain('const a = useOS');
		expect(out[0].fileContents).toContain('const b = useOS');
		expect(out[0].fileContents).not.toContain('=> ({');
		expect(mocked.runMock).not.toHaveBeenCalled();
	});

	it('invokes fixer for setState in render body', async () => {
		mocked.runMock.mockImplementation(async (file: FileOutputType) => file);

		const input = [
			makeFile({
				filePath: 'src/App.tsx',
				fileContents:
					"import { useState } from 'react';\nexport function App() { const [x, setX] = useState(0); setX(1); return <div>{x}</div>; }",
			}),
		];

		await expect(runPreDeploySafetyGate(makeArgs(input))).resolves.toBeTruthy();
		expect(mocked.runMock).toHaveBeenCalledTimes(1);
	});

	it('invokes fixer for useEffect missing deps when setting state', async () => {
		mocked.runMock.mockImplementation(async (file: FileOutputType) => file);

		const input = [
			makeFile({
				filePath: 'src/App.tsx',
				fileContents:
					"import { useEffect, useState } from 'react';\nexport function App() { const [x,setX] = useState(0); useEffect(() => { setX(1); }); return <div>{x}</div> }",
			}),
		];

		await expect(runPreDeploySafetyGate(makeArgs(input))).resolves.toBeTruthy();
		expect(mocked.runMock).toHaveBeenCalledTimes(1);
	});

	it('never throws if RealtimeCodeFixer constructor throws', async () => {
		mocked.constructorShouldThrow = true;

		const input = [
			makeFile({
				filePath: 'src/App.tsx',
				fileContents: "const x = useOS(s => ({ a: s.a }));\nexport default function App() { return null }",
			}),
		];

		const out = await runPreDeploySafetyGate(makeArgs(input));
		expect(out).toHaveLength(1);
		expect(out[0].filePath).toBe('src/App.tsx');
		expect(mocked.runMock).not.toHaveBeenCalled();
		expect(warnSpy).toHaveBeenCalled();
	});

	it('never throws if fixer run rejects; returns original', async () => {
		mocked.runMock.mockRejectedValueOnce(new Error('fixer failed'));

		const input = [
			makeFile({
				filePath: 'src/App.tsx',
				fileContents: "const x = useOS(s => ({ a: s.a }));\nexport default function App() { return null }",
			}),
		];

		const out = await runPreDeploySafetyGate(makeArgs(input));
		expect(out[0].fileContents).toBe(input[0].fileContents);
		expect(warnSpy).toHaveBeenCalled();
	});

	it('never throws if fixer run throws; returns original', async () => {
		mocked.runMock.mockImplementationOnce(() => {
			throw new Error('fixer threw');
		});

		const input = [
			makeFile({
				filePath: 'src/App.tsx',
				fileContents: "const x = useOS(s => ({ a: s.a }));\nexport default function App() { return null }",
			}),
		];

		const out = await runPreDeploySafetyGate(makeArgs(input));
		expect(out[0].fileContents).toBe(input[0].fileContents);
		expect(warnSpy).toHaveBeenCalled();
	});

	it('never throws on invalid syntax; still returns files', async () => {
		mocked.runMock.mockImplementation(async (file: FileOutputType) => file);

		const input = [
			makeFile({
				filePath: 'src/App.tsx',
				fileContents: 'export const =',
			}),
		];

		await expect(runPreDeploySafetyGate(makeArgs(input))).resolves.toHaveLength(1);
		expect(warnSpy).toHaveBeenCalled();
	});

	it('fuzz: never throws across random file contents', async () => {
		mocked.runMock.mockImplementation(async (file: FileOutputType) => file);

		const rng = makeSeededRng(123456);
		const files: FileOutputType[] = [];
		for (let i = 0; i < 200; i++) {
			files.push(
				makeFile({
					filePath: `src/Fuzz${i}.tsx`,
					fileContents: randomAscii(rng, 200),
				}),
			);
		}

		const out = await runPreDeploySafetyGate(makeArgs(files));
		expect(out).toHaveLength(200);
	});
});

describe('detectPreDeploySafetyFindings', () => {
	it('never throws on random input', () => {
		const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
		expect(() => detectPreDeploySafetyFindings('<<< not ts >>>')).not.toThrow();
		const out = detectPreDeploySafetyFindings('<<< not ts >>>');
		expect(Array.isArray(out)).toBe(true);
		// Parser should fail and log
		expect(spy).toHaveBeenCalled();
		spy.mockRestore();
	});

	it('fuzz: never throws across random strings', () => {
		const rng = makeSeededRng(424242);
		for (let i = 0; i < 200; i++) {
			expect(() => detectPreDeploySafetyFindings(randomAscii(rng, 200))).not.toThrow();
		}
	});
});

import { describe, it, expect } from 'vitest';
import { providerLabel } from './AuthService';

describe('providerLabel', () => {
	it('maps known OAuth providers to display names', () => {
		expect(providerLabel('google')).toBe('Google');
		expect(providerLabel('github')).toBe('GitHub');
		expect(providerLabel('cloudflare')).toBe('Cloudflare');
	});

	it('falls back for email or unknown/missing providers', () => {
		expect(providerLabel('email')).toBe('a different sign-in method');
		expect(providerLabel('unknown')).toBe('a different sign-in method');
		expect(providerLabel(null)).toBe('a different sign-in method');
		expect(providerLabel(undefined)).toBe('a different sign-in method');
	});
});

/**
 * Model Test Service
 * Handles testing of model configurations with user API keys
 */

import { BaseService } from './BaseService';
import { AIModels } from '../../agents/inferutils/config.types';
import { infer, InferError } from '../../agents/inferutils/core';
import { createUserMessage } from '../../agents/inferutils/common';
import type { TestResult, ModelTestRequest, ModelTestResult } from '../types';
import { isErrorWithMessage } from '../types';

export class ModelTestService extends BaseService {
    /**
     * Test a model configuration by making a simple chat request using core inference
     */
    async testModelConfig({
        modelConfig,
        userApiKeys,
        testPrompt = "Hello! Please respond with 'Test successful' to confirm the connection is working."
    }: ModelTestRequest): Promise<ModelTestResult> {
        const startTime = Date.now();
        const modelName: string = modelConfig.name;
        const cleanModelName = modelName.replace(/\[.*?\]/, ''); // Remove provider prefix for display

        try {
            const testMessage = createUserMessage(testPrompt);

            // Use core inference system to test the model configuration
            const response = await infer({
                env: this.env,
                metadata: { agentId: `test-${Date.now()}`, userId: 'system' }, // Generate unique test ID
                messages: [testMessage],
                modelName: modelName,
                maxTokens: Math.min(modelConfig.max_tokens || 100, 100), // Limit to 100 tokens for test
                temperature: modelConfig.temperature || 0.1,
                reasoning_effort: modelConfig.reasoning_effort,
                actionKey: 'testModelConfig',
                runtimeOverrides: {
                    userApiKeys
                }
            });

            const endTime = Date.now();
            const latencyMs = endTime - startTime;

            const content = response.string || '';

            return {
                success: true,
                responsePreview: content.length > 100 ? content.substring(0, 100) + '...' : content,
                latencyMs,
                modelUsed: cleanModelName,
            };

        } catch (error: unknown) {
            const endTime = Date.now();
            const latencyMs = endTime - startTime;

            // Handle InferError and other errors from core system
            let rawError = 'Unknown error occurred';

            if (error instanceof InferError) {
                rawError = error.message;
            } else if (error instanceof Error) {
                rawError = error.message;
            } else if (isErrorWithMessage(error)) {
                // Handle error objects from the core system
                if (error.message) {
                    rawError = error.message;
                } else if (error.error?.message) {
                    rawError = error.error.message;
                } else {
                    rawError = JSON.stringify(error);
                }
            } else {
                rawError = String(error);
            }

            return {
                success: false,
                error: rawError,
                latencyMs,
                modelUsed: cleanModelName
            };
        }
    }

    /**
     * Test a specific provider's API key using core inference
     */
    async testProviderKey(provider: string, apiKey: string): Promise<TestResult> {
        const startTime = Date.now();

        try {
            // Get a simple model for this provider to test with
            const testModel = this.getTestModelForProvider(provider);
            if (!testModel) {
                return {
                    success: false,
                    error: `No test model available for provider: ${provider}`
                };
            }

            // Create a userApiKeys map with the test key
            const testApiKeys = new Map<string, string>();
            testApiKeys.set(provider, apiKey);

            // Create test message using core abstractions
            const testMessage = createUserMessage('Test connection. Please respond with "OK".');

            // Use core inference system to test the provider key
            const response = await infer({
                env: this.env,
                metadata: { agentId: `provider-test-${Date.now()}`, userId: 'system' }, // Generate unique test ID
                messages: [testMessage],
                modelName: testModel,
                maxTokens: 10,
                temperature: 0,
                actionKey: 'testModelConfig',
                runtimeOverrides: {
                    userApiKeys: Object.fromEntries(testApiKeys)
                }
            });

            const endTime = Date.now();
            const cleanModelName = testModel.replace(/\[.*?\]/, '');

            if (response.string && response.string.trim()) {
                return {
                    success: true,
                    model: cleanModelName,
                    latencyMs: endTime - startTime
                };
            } else {
                return {
                    success: false,
                    error: 'No response received from model'
                };
            }

        } catch (error: unknown) {
            const endTime = Date.now();
            const latencyMs = endTime - startTime;

            // Handle InferError and other errors from core system
            let rawError = 'Connection test failed';

            if (error instanceof InferError) {
                rawError = error.message;
            } else if (error instanceof Error) {
                rawError = error.message;
            } else if (isErrorWithMessage(error)) {
                // Handle error objects from the core system
                if (error.message) {
                    rawError = error.message;
                } else if (error.error?.message) {
                    rawError = error.error.message;
                } else {
                    rawError = JSON.stringify(error);
                }
            } else {
                rawError = String(error);
            }

            return {
                success: false,
                error: rawError,
                latencyMs
            };
        }
    }

    /**
     * Get a simple test model for a given provider
     */
    private getTestModelForProvider(provider: string): string | null {
        const testModels: Record<string, string> = {
            'openai': AIModels.OPENAI_5_MINI,
            'anthropic': AIModels.CLAUDE_4_SONNET,
            'google-ai-studio': AIModels.GEMINI_2_5_FLASH,
            'gemini': AIModels.GEMINI_2_5_FLASH,
            // 'openrouter': AIModels.OPENROUTER_QWEN_3_CODER, // Removed - not available
            // 'cerebras': AIModels.CEREBRAS_GPT_OSS
        };

        return testModels[provider] || null;
    }
}

import { beforeEach, describe, expect, it, vi } from 'vitest';
// Import via the same specifier the handler uses so `instanceof` matches the
// class identity inside space-preview.ts (Vite resolves the `shared` alias).
import { RateLimitExceededError } from 'shared/types/errors';

// getPreviewVersion is always 0 here (no visibility revocation under test).
vi.mock('../../database/services/AppService', () => ({
	AppService: class {
		async getPreviewVersion() {
			return 0;
		}
	},
}));

// Simulate the per-token limiter: allow up to LIMIT calls per token, then throw.
const LIMIT = 3;
const callsByToken = new Map<string, number>();
vi.mock('../../services/rate-limit/rateLimits', () => ({
	RateLimitService: {
		enforceSpacePreviewRateLimit: async (
			_env: unknown,
			_config: unknown,
			tokenId: string,
		) => {
			const n = (callsByToken.get(tokenId) ?? 0) + 1;
			callsByToken.set(tokenId, n);
			if (n > LIMIT) {
				throw new RateLimitExceededError('Space preview rate limit exceeded', 'spacePreview');
			}
		},
	},
}));

const { handleSpacePreview } = await import('./space-preview');
const { signSpacePreviewToken } = await import('../../utils/spacePreviewToken');

const JWT_SECRET = '[REDACTED]';

type HandlerEnv = Parameters<typeof handleSpacePreview>[1];

function makeEnv(): HandlerEnv {
	const stub = {
		fetch: async () => new Response('ok', { headers: { 'content-type': 'text/html' } }),
	};
	return {
		JWT_SECRET,
		CUSTOM_DOMAIN: 'example.com',
		CUSTOM_PREVIEW_DOMAIN: '',
		SPACE_DO: { idFromName: (n: string) => n, get: () => stub },
	} as unknown as HandlerEnv;
}

function previewRequest(token: string): Request {
	return new Request(
		`https://example.com/space/space-a/preview/main/?t=${encodeURIComponent(token)}`,
	);
}

beforeEach(() => {
	callsByToken.clear();
});

describe('handleSpacePreview rate limiting', () => {
	it('returns 200 up to the limit then 429 for sustained same-token traffic', async () => {
		const env = makeEnv();
		const token = await signSpacePreviewToken(env, {
			spaceName: 'space-a',
			branch: 'main',
			userId: 'user-a',
			previewVersion: 0,
		});
		const req = () => handleSpacePreview(previewRequest(token), env, 'space-a', 'main');

		for (let i = 0; i < LIMIT; i++) {
			expect((await req()).status).toBe(200);
		}
		// Over the limit.
		expect((await req()).status).toBe(429);
	});

	it('counts distinct tokens separately', async () => {
		const env = makeEnv();
		const tokenA = await signSpacePreviewToken(env, {
			spaceName: 'space-a',
			branch: 'main',
			userId: 'user-a',
			previewVersion: 0,
		});
		const tokenB = await signSpacePreviewToken(env, {
			spaceName: 'space-a',
			branch: 'main',
			userId: 'user-b',
			previewVersion: 0,
		});

		// Exhaust token A.
		for (let i = 0; i < LIMIT; i++) {
			await handleSpacePreview(previewRequest(tokenA), env, 'space-a', 'main');
		}
		expect((await handleSpacePreview(previewRequest(tokenA), env, 'space-a', 'main')).status).toBe(429);
		// Token B is unaffected.
		expect((await handleSpacePreview(previewRequest(tokenB), env, 'space-a', 'main')).status).toBe(200);
	});
});

name: Deploy (release-live)

on:
  push:
    branches: [release-live]
  workflow_dispatch:

permissions:
  contents: read

concurrency:
  group: deploy-release-live
  cancel-in-progress: false

jobs:
  test-build:
    runs-on: ubuntu-latest
    timeout-minutes: 30

    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup Bun
        uses: oven-sh/setup-bun@v1
        with:
          bun-version: latest

      - name: Cache Bun install cache
        uses: actions/cache@v4
        with:
          path: ~/.bun/install/cache
          key: ${{ runner.os }}-bun-${{ hashFiles('bun.lock') }}
          restore-keys: |
            ${{ runner.os }}-bun-

      - name: Install dependencies
        run: bun install --frozen-lockfile

      # Intentionally skipping lint/typecheck; CI already enforces those.
      - name: Test
        run: bun run test

  deploy:
    runs-on: ubuntu-latest
    timeout-minutes: 45
    needs: test-build

    # Skip deploy for forks (they won't have secrets anyway)
    if: github.repository_owner == 'cloudflare'

    env:
      CI: true
      WRANGLER_NON_INTERACTIVE: true

      # Production runs on an account with Cloudflare Artifacts access. Keep the
      # ARTIFACTS binding: the deploy script drops it unless this is "true".
      ENABLE_ARTIFACTS: "true"

      # Prefer repo variables for non-sensitive config.
      CUSTOM_DOMAIN: ${{ vars.CUSTOM_DOMAIN }}
      CUSTOM_PREVIEW_DOMAIN: ${{ vars.CUSTOM_PREVIEW_DOMAIN }}
      MAX_SANDBOX_INSTANCES: ${{ vars.MAX_SANDBOX_INSTANCES }}
      SANDBOX_INSTANCE_TYPE: ${{ vars.SANDBOX_INSTANCE_TYPE }}
      DISPATCH_NAMESPACE: ${{ vars.DISPATCH_NAMESPACE }}
      TEMPLATES_REPOSITORY: ${{ vars.TEMPLATES_REPOSITORY }}
      ALLOCATION_STRATEGY: ${{ vars.ALLOCATION_STRATEGY }}
      ENVIRONMENT: ${{ vars.ENVIRONMENT }}
      PLATFORM_MODEL_PROVIDERS: ${{ vars.PLATFORM_MODEL_PROVIDERS }}
      USE_CLOUDFLARE_IMAGES: ${{ vars.USE_CLOUDFLARE_IMAGES }}
      CLOUDFLARE_AI_GATEWAY_TOKEN: ${{ secrets.CLOUDFLARE_AI_GATEWAY_TOKEN }}
      CLOUDFLARE_AI_GATEWAY_URL: ${{ vars.CLOUDFLARE_AI_GATEWAY_URL }}

    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: 22

      - name: Setup Bun
        uses: oven-sh/setup-bun@v1
        with:
          bun-version: latest

      - name: Cache Bun install cache
        uses: actions/cache@v4
        with:
          path: ~/.bun/install/cache
          key: ${{ runner.os }}-bun-${{ hashFiles('bun.lock') }}
          restore-keys: |
            ${{ runner.os }}-bun-

      - name: Install dependencies
        run: bun install --frozen-lockfile

      - name: Add local binaries to PATH
        run: echo "${{ github.workspace }}/node_modules/.bin" >> "$GITHUB_PATH"

      - name: Deploy via deploy script
        env:
          # Secrets used by deploy script to create/sync .prod.vars.
          CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          CLOUDFLARE_ACCOUNT_ID: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          CLOUDFLARE_AI_GATEWAY_TOKEN: ${{ secrets.CLOUDFLARE_AI_GATEWAY_TOKEN }}
          CLOUDFLARE_AI_GATEWAY_URL: ${{ secrets.CLOUDFLARE_AI_GATEWAY_URL }}

          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}
          OPENAI_API_KEY: ${{ secrets.OPENAI_API_KEY }}
          GOOGLE_AI_STUDIO_API_KEY: ${{ secrets.GOOGLE_AI_STUDIO_API_KEY }}
          OPENROUTER_API_KEY: ${{ secrets.OPENROUTER_API_KEY }}
          GROQ_API_KEY: ${{ secrets.GROQ_API_KEY }}

          GOOGLE_CLIENT_ID: ${{ secrets.GOOGLE_CLIENT_ID }}
          GOOGLE_CLIENT_SECRET: ${{ secrets.GOOGLE_CLIENT_SECRET }}
          GITHUB_CLIENT_ID: ${{ secrets.GITHUB_CLIENT_ID }}
          GITHUB_CLIENT_SECRET: ${{ secrets.GITHUB_CLIENT_SECRET }}
          CLOUDFLARE_OAUTH_CLIENT_ID: ${{ vars.PROD_CLOUDFLARE_OAUTH_CLIENT_ID }}
          CLOUDFLARE_OAUTH_CLIENT_SECRET: ${{ secrets.PROD_CLOUDFLARE_OAUTH_CLIENT_SECRET }}
          CF_OAUTH_ENCRYPTION_KEY: ${{ secrets.PROD_CF_OAUTH_ENCRYPTION_KEY }}

          JWT_SECRET: ${{ secrets.JWT_SECRET }}
          SENTRY_DSN: ${{ secrets.SENTRY_DSN }}
          AI_PROXY_JWT_SECRET: ${{ secrets.AI_PROXY_JWT_SECRET }}
        run: bun scripts/deploy.ts

